import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { resolve, basename } from 'node:path';
const session = basename(process.cwd());
function run(...args) {
  const child = spawnSync('agent-browser', ['--session', session, ...args], { encoding: 'utf8', timeout: 15000 });
  if (child.error || child.status !== 0) throw new Error(child.error?.message || child.stderr || 'Browser check failed');
  process.stdout.write(child.stdout);
  return child.stdout;
}
try {
  run('open', pathToFileURL(resolve('index.html')).href);
  const snapshot = run('snapshot', '-i');
  const match = snapshot.match(/link "Contact" \[ref=(e[0-9]+)\]/);
  if (!match) throw new Error('Contact link is absent from the snapshot');
  run('click', '@' + match[1]);
  run('snapshot', '-i');
  const url = run('get', 'url');
  if (!url.includes('#contact')) throw new Error('Contact did not navigate to the section');
} finally {
  spawnSync('agent-browser', ['--session', session, 'close'], { encoding: 'utf8', timeout: 10000 });
}
